26-09-22 16:12:01.816234+00","changed":true,"before":{"primary_category_id":"63b5e015-cc2c-425d-8b52-41f751cbbd9b","subcategory_id":null,"stacks":[{"primary_category_id":"63b5e015-cc2c-425d-8b52-41f751cbbd9b","subcategory_id":null,"sort_order":0}],"rows":[{"created_at":"2026-09-22T16:06:44.571503+00:00","id":"9060c3df-6997-4196-8bc5-c5a324c7d04c","primary_category_id":"63b5e015-cc2c-425d-8b52-41f751cbbd9b","resume_id":"74cf6a3b-256b-41b1-932e-202e3f373167","sort_order":0,"subcategory_id":null}]},"after":{"primary_category_id":"63b5e015-cc2c-425d-8b52-41f751cbbd9b","subcategory_id":null,"stacks":[{"primary_category_id":"63b5e015-cc2c-425d-8b52-41f751cbbd9b","subcategory_id":null,"sort_order":0},{"primary_category_id":"9010fba7-b6f5-4552-b1ea-7941b48c82f5","subcategory_id":null,"sort_order":1},{"primary_category_id":"67e65ffd-dd98-4904-9549-dd3e4302e07a","subcategory_id":null,"sort_order":2}]}},{"id":"a59353b5-a33c-4783-bc79-f55ad2e39745","source_hash":"e8868c67a54e339e0db8d70242a2556a","updated_at":"2026-09-22 16:31:48.932129+00","changed":true,"before":{"primary_category_id":"eaae452b-5923-426d-8391-bafd5583efac","subcategory_id":null,"stacks":[{"primary_category_id":"eaae452b-5923-426d-8391-bafd5583efac","subcategory_id":null,"sort_order":0}],"rows":[{"created_at":"2026-09-22T16:22:46.580621+00:00","id":"6d790e56-4462-4f24-aa7b-ba93e9650fcf","primary_category_id":"eaae452b-5923-426d-8391-bafd5583efac","resume_id":"a59353b5-a33c-4783-bc79-f55ad2e39745","sort_order":0,"subcategory_id":null}]},"after":{"primary_category_id":"eaae452b-5923-426d-8391-bafd5583efac","subcategory_id":null,"stacks":[{"primary_category_id":"eaae452b-5923-426d-8391-bafd5583efac","subcategory_id":null,"sort_order":0},{"primary_category_id":"15a0022e-8edc-4000-a3a2-e02726196f19","subcategory_id":"4bc9e26d-236a-4ff5-b2dd-59cc0a28ec4e","sort_order":1},{"primary_category_id":"15a0022e-8edc-4000-a3a2-e02726196f19","subcategory_id":"3b124706-8495-4df3-8b27-5ab674f589ff","sort_order":2}]}}]'::jsonb);
do $tagging$
declare p jsonb; r public.resumes; current_tags jsonb; original_fields jsonb;
begin
  if (select count(*) from tagging_plan)<>44 then raise exception 'Expected exactly 44 reviewed originals'; end if;
  perform 1 from public.resumes where id in (select (data->>'id')::uuid from tagging_plan) order by id for update;
  for p in select data from tagging_plan order by data->>'id' loop
    select * into r from public.resumes where id=(p->>'id')::uuid;
    if not found or r.resume_type<>'ORIGINAL' or r.status<>'ACTIVE' then raise exception 'Resume missing or scope changed: %',p->>'id'; end if;
    if md5(coalesce(r.resume_text,'') || coalesce(r.structured_content::text,''))<>p->>'source_hash'
      or r.updated_at is distinct from (p->>'updated_at')::timestamptz
      or to_jsonb(r.primary_category_id) is distinct from p->'before'->'primary_category_id'
      or coalesce(to_jsonb(r.subcategory_id),'null'::jsonb) is distinct from p->'before'->'subcategory_id' then
      raise exception 'Resume changed since review: %',r.id;
    end if;
    select coalesce(jsonb_agg(jsonb_build_object('primary_category_id',primary_category_id,'subcategory_id',subcategory_id,'sort_order',sort_order) order by sort_order,id),'[]')
      into current_tags from public.resume_tech_stacks where resume_id=r.id;
    if current_tags<>p->'before'->'stacks' then raise exception 'Tags changed since review: %',r.id; end if;
    if jsonb_array_length(p->'after'->'stacks') not between 1 and 12 then raise exception 'Invalid stack count'; end if;
    if (p->>'changed')::boolean then
      original_fields := to_jsonb(r)-'primary_category_id'-'subcategory_id'-'updated_at';
      delete from public.resume_tech_stacks where resume_id=r.id;
      insert into public.resume_tech_stacks(resume_id,primary_category_id,subcategory_id,sort_order)
        select r.id,(s->>'primary_category_id')::uuid,(s->>'subcategory_id')::uuid,(s->>'sort_order')::integer
        from jsonb_array_elements(p->'after'->'stacks') s;
      update public.resumes set primary_category_id=(p->'after'->>'primary_category_id')::uuid,
        subcategory_id=(p->'after'->>'subcategory_id')::uuid where id=r.id;
      if (select to_jsonb(x)-'primary_category_id'-'subcategory_id'-'updated_at' from public.resumes x where id=r.id)<>original_fields then
        raise exception 'Unexpected non-tag field change: %',r.id;
      end if;
    end if;
    select coalesce(jsonb_agg(jsonb_build_object('primary_category_id',primary_category_id,'subcategory_id',subcategory_id,'sort_order',sort_order) order by sort_order,id),'[]')
      into current_tags from public.resume_tech_stacks where resume_id=r.id;
    if current_tags<>p->'after'->'stacks' then raise exception 'Tag verification failed: %',r.id; end if;
  end loop;
end $tagging$;
select count(*) as reviewed, count(*) filter(where (data->>'changed')::boolean) as updated,
  count(*) filter(where not (data->>'changed')::boolean) as unchanged from tagging_plan;
rollback;
